#!/usr/bin/env bun
// Content codegen: content/portfolio.yaml + content/prose/*.md -> shared/content.generated.ts.
//
// The generated file is COMMITTED and is the single typed source the app, worker, and
// tests consume (via shared/resume-canonical.ts). This script is never imported at
// runtime; it only regenerates that file.
//
//   bun run content:build    regenerate the committed file
//   bun run content:check    render in memory and byte-compare (fails on drift, no write)
//
// Determinism: the emitted object is rebuilt in a fixed key order with optional sections
// normalized (absent arrays -> [], absent resumePdfPath -> null), then serialized with
// JSON.stringify(obj, null, 2). Same inputs -> byte-identical output.
import { existsSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import YAML from 'yaml'
import { z } from 'zod'

const repoRoot = fileURLToPath(new URL('../', import.meta.url))
const path = (rel: string) => fileURLToPath(new URL(rel, import.meta.url))

const YAML_PATH = path('../content/portfolio.yaml')
const SUMMARY_PROSE_PATH = path('../content/prose/summary.md')
const FAVICON_PATH = path('../public/icon.svg')
const GENERATED_PATH = path('../shared/content.generated.ts')

const HEADER = `// AUTO-GENERATED by scripts/build-content.ts from content/portfolio.yaml + content/prose/*.md.
// Do not edit by hand. Run \`bun run content:build\` to regenerate.
`

const nonEmpty = z.string().trim().min(1)

const educationSchema = z.strictObject({
  school: nonEmpty,
  degree: nonEmpty,
  coursework: z.array(nonEmpty).default([]),
})

const evidenceItemSchema = z.strictObject({
  id: nonEmpty,
  company: nonEmpty,
  role: nonEmpty,
  period: nonEmpty,
  description: nonEmpty,
  bullets: z.array(nonEmpty).min(1),
})

const projectSchema = z.strictObject({
  id: nonEmpty,
  name: nonEmpty,
  period: nonEmpty,
  description: nonEmpty,
  bullets: z.array(nonEmpty).min(1),
})

const proofPointSchema = z.strictObject({
  sourceId: nonEmpty,
  title: nonEmpty,
  detail: nonEmpty,
})

const portfolioSchema = z
  .strictObject({
    name: nonEmpty,
    title: nonEmpty,
    assistantName: nonEmpty,
    shortName: nonEmpty,
    headerLabel: nonEmpty,
    contact: z.strictObject({
      email: nonEmpty,
      location: nonEmpty,
      linkedinPath: nonEmpty,
    }),
    seo: z.strictObject({
      title: nonEmpty,
      description: nonEmpty,
      ogTitle: nonEmpty,
      ogDescription: nonEmpty,
      themeColor: nonEmpty,
    }),
    resumePdfPath: nonEmpty.optional(),
    targetRoles: z.array(nonEmpty).min(1),
    starterPrompts: z.array(nonEmpty).min(1),
    homepage: z.strictObject({
      openToLabel: nonEmpty,
      roleFocus: nonEmpty,
      heroHeadline: nonEmpty,
      ctaHeadline: nonEmpty,
      ctaSubtext: nonEmpty,
      proofPoints: z.array(proofPointSchema).default([]),
    }),
    // A list so multiple degrees are supported; at least one is required because the
    // compact homepage stat box surfaces the primary (first) degree.
    education: z.array(educationSchema).min(1),
    experience: z.array(evidenceItemSchema).default([]),
    projects: z.array(projectSchema).default([]),
    leadership: z
      .array(
        z.strictObject({
          organization: nonEmpty,
          role: nonEmpty,
          period: nonEmpty,
          highlights: z.array(nonEmpty).default([]),
        })
      )
      .default([]),
    certifications: z
      .array(
        z.strictObject({
          name: nonEmpty,
          issuer: nonEmpty,
          period: nonEmpty,
          highlights: z.array(nonEmpty).default([]),
        })
      )
      .default([]),
    awards: z
      .array(
        z.strictObject({
          name: nonEmpty,
          period: nonEmpty,
          detail: nonEmpty,
        })
      )
      .default([]),
    skills: z.strictObject({
      strong: z.array(nonEmpty).default([]),
      moderate: z.array(nonEmpty).default([]),
      gaps: z.array(nonEmpty).default([]),
    }),
  })
  .superRefine((data, ctx) => {
    const evidenceIds = [
      ...data.experience.map((item) => item.id),
      ...data.projects.map((item) => item.id),
    ]
    const seen = new Set<string>()
    for (const id of evidenceIds) {
      if (seen.has(id)) {
        ctx.addIssue({ code: 'custom', message: `Duplicate evidence id: "${id}"` })
      }
      seen.add(id)
    }
    const idSet = new Set(evidenceIds)
    data.homepage.proofPoints.forEach((proofPoint, index) => {
      if (!idSet.has(proofPoint.sourceId)) {
        ctx.addIssue({
          code: 'custom',
          path: ['homepage', 'proofPoints', index, 'sourceId'],
          message: `proofPoints[${index}].sourceId "${proofPoint.sourceId}" does not match any experience or project id`,
        })
      }
    })
  })

function fail(message: string): never {
  console.error(`content:build error: ${message}`)
  process.exit(1)
}

function readProse(filePath: string, label: string): string {
  if (!existsSync(filePath)) {
    fail(`missing prose file: ${label}`)
  }
  // Normalize CRLF so output is byte-identical regardless of checkout line endings.
  const text = readFileSync(filePath, 'utf8').replace(/\r\n/g, '\n').trim()
  if (text.length === 0) {
    fail(`empty prose file: ${label}`)
  }
  return text
}

function render(): string {
  const raw = YAML.parse(readFileSync(YAML_PATH, 'utf8'))
  const parsed = portfolioSchema.safeParse(raw)
  if (!parsed.success) {
    fail(`content/portfolio.yaml failed validation:\n${z.prettifyError(parsed.error)}`)
  }
  const facts = parsed.data

  const summary = readProse(SUMMARY_PROSE_PATH, 'content/prose/summary.md')

  // Referenced public assets must exist on disk.
  if (!existsSync(FAVICON_PATH)) {
    fail('missing favicon asset: public/icon.svg')
  }
  if (facts.resumePdfPath) {
    const rel = facts.resumePdfPath
    // Require a canonical, same-origin, root-relative path. Parsing against a sentinel
    // origin rejects protocol-relative "//host" and absolute URLs (both would become an
    // off-site href), plus traversal, backslashes, and anything the URL parser rewrites.
    const sentinel = 'https://portfolio.invalid'
    let pathname = ''
    try {
      const parsed = new URL(rel, sentinel)
      pathname = parsed.pathname
      if (
        parsed.origin !== sentinel ||
        pathname !== rel ||
        rel.includes('..') ||
        rel.includes('\\')
      ) {
        throw new Error('non-canonical')
      }
    } catch {
      fail(`resumePdfPath must be a canonical root-relative path under /public (got "${rel}")`)
    }
    const publicDir = fileURLToPath(new URL('../public/', import.meta.url))
    const assetPath = fileURLToPath(new URL(`../public${pathname}`, import.meta.url))
    if (
      !assetPath.startsWith(publicDir) ||
      !existsSync(assetPath) ||
      !statSync(assetPath).isFile()
    ) {
      fail(`resumePdfPath references a missing file under /public: ${rel}`)
    }
  }

  // Rebuild in a fixed key order with optional scalars normalized so the emitted
  // shape is stable regardless of which optional sections the source fills.
  const content = {
    name: facts.name,
    title: facts.title,
    assistantName: facts.assistantName,
    shortName: facts.shortName,
    headerLabel: facts.headerLabel,
    contact: facts.contact,
    seo: facts.seo,
    resumePdfPath: facts.resumePdfPath ?? null,
    summary,
    targetRoles: facts.targetRoles,
    starterPrompts: facts.starterPrompts,
    homepage: facts.homepage,
    education: facts.education,
    experience: facts.experience,
    projects: facts.projects,
    leadership: facts.leadership,
    certifications: facts.certifications,
    awards: facts.awards,
    skills: facts.skills,
  }

  return `${HEADER}export const generatedContent = ${JSON.stringify(content, null, 2)} as const\n`
}

const isCheck = process.argv.includes('--check')
const rendered = render()

if (isCheck) {
  const committed = existsSync(GENERATED_PATH) ? readFileSync(GENERATED_PATH, 'utf8') : ''
  if (committed !== rendered) {
    fail('shared/content.generated.ts is out of date. Run `bun run content:build`.')
  }
  console.log('content:check OK (shared/content.generated.ts is up to date)')
} else {
  const current = existsSync(GENERATED_PATH) ? readFileSync(GENERATED_PATH, 'utf8') : ''
  if (current !== rendered) {
    writeFileSync(GENERATED_PATH, rendered)
    console.log(`content:build wrote ${GENERATED_PATH.replace(repoRoot, '')}`)
  } else {
    console.log('content:build OK (no changes)')
  }
}
